import{_ as t,c as n,o as r,a2 as s}from"./chunks/framework.PGES7OoM.js";const o="/assets/curvy-full-flow.DmT0lbAd.png",a="/assets/curvy-receiver-flow.BFI51XEh.png",y=JSON.parse(`{"title":"Receiving funds privately","description":"","frontmatter":{"rawMarkdown":"# Receiving funds privately\\n\\n**Alice, the client**, wants to send a salary to her **consultant, Bob**.\\n\\nAlice uses MetaMask with Ledger to manage her company's treasury, while Bob, a privacy-savvy crypto professional, uses Curvy to ensure his clients don't get unnecessary insight into his earnings and spending.\\n\\nBob has provided Alice with instructions to complete the payment to his ENS: bob.curvy.name, or to simply\\nopen https://bob.curvy.name and continue with payment there.\\n\\nBob made it clear that **he only accepts payment in USDC, but hasn't specified which network to use**.\\n\\nWithout asking, Alice sent the funds to Bob's private address on Ethereum, but was reassured by Bob that *the system\\nhe's using should pick up transfers on any of the [supported networks](/for-users/#supported-networks-and-tokens) — Polygon, BSC, Arbitrum, Optimism, Linea, Base, Gnosis, or even Solana.*\\n\\n**Bob uses Curvy, but Alice, the sender, can keep using Ledger + MetaMask without knowing what Curvy is.**\\n\\n![Receiving funds privately](./curvy-full-flow.png)\\n\\n## Steps explained in detail\\n\\n### 🔵 Alice\\n\\n**1.** Alice enters \`bob.curvy.name\` into her wallet of choice. In the background, an **ENS resolver** powered by the **Curvy SDK**\\nfetches Bob's public keys from the **Identity Registry**.\\n\\n**2.** Using the **Curvy SDK**, a random nonce, and Bob's public keys, a new **Portal** address is generated to which Bob can receive funds; no contract is deployed at that address yet. The resolved Portal is recorded so that the **Portal Broadcasters** can later pick it up.\\n\\n**3.** Alice sends the funds to the generated Portal address, as she would to any regular address.\\n\\n### ⚫ Curvy\\n\\n**4.** After observing that a Portal address has received any of the supported funds, the **Portal Broadcasters** have the necessary incentive to\\ndeploy the **Portal** contract through the **Portal Factory**. Because the address of the Portal is deterministically calculated,\\nthe deployment lands exactly where the funds are: on networks without the aggregator, an entry Portal automatically bridges the funds over the\\ncross-chain bridge; on the network with the aggregator, a shielding Portal shields them directly into the **Privacy Aggregator** (**Aggregator.sol**).\\n\\n**6.** The **Batch Prover** picks up the pending shielded notes, constructs a commitment proof for the new notes batch, and commits it on-chain to\\n**Aggregator.sol**. After successful on-chain verification, the new note becomes part of the committed Notes tree.\\n\\n### 🟢 Bob\\n\\n**7.** Some unknown time later, Bob logs into his **Curvy App**. In the background, immediately upon starting, the Curvy App,\\nusing the open-source **Curvy SDK**, syncs its local Merkle tree from the **Indexer**, which serves as a fast index of on-chain events emitted by **Aggregator.sol**.\\n\\n![Receiver flow](./curvy-receiver-flow.png)\\n\\nIn Bob's browser, the **Curvy SDK** simultaneously scans the synced notes with his private keys to\\ndetect which notes are secretly in his ownership and to decrypt their balances.\\n\\n> [!NOTE]\\n> Steps **5a/5b** (transfer proofs) and **8** (withdrawal request) from the drawing above belong to the other two flows: [Sending funds privately](./sending-funds-privately.md) and [Unshielding funds privately](./unshielding-funds-privately.md).\\n\\n> [!IMPORTANT]\\n> From the perspective of an on-chain observer, Alice has sent funds to a regular EOA address to which a smart contract (Portal) was later deployed by the Portal Broadcaster. This deployment moved the funds to the Curvy Privacy Protocol (Aggregator.sol), **and most importantly, the new owner of these funds (Bob) is completely hidden**.\\n","rawMarkdownPath":"/_raw/for-the-curious/walkthroughs/receiving-funds-privately.md","rawMarkdownTitle":"Receiving funds privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-the-curious/walkthroughs/receiving-funds-privately.md"},"headers":[],"relativePath":"for-the-curious/walkthroughs/receiving-funds-privately.md","filePath":"for-the-curious/walkthroughs/receiving-funds-privately.md","lastUpdated":1784144016000}`),i={name:"for-the-curious/walkthroughs/receiving-funds-privately.md"};function h(d,e,l,c,u,g){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="receiving-funds-privately" tabindex="-1">Receiving funds privately <a class="header-anchor" href="#receiving-funds-privately" aria-label="Permalink to &quot;Receiving funds privately&quot;">​</a></h1><p><strong>Alice, the client</strong>, wants to send a salary to her <strong>consultant, Bob</strong>.</p><p>Alice uses MetaMask with Ledger to manage her company&#39;s treasury, while Bob, a privacy-savvy crypto professional, uses Curvy to ensure his clients don&#39;t get unnecessary insight into his earnings and spending.</p><p>Bob has provided Alice with instructions to complete the payment to his ENS: bob.curvy.name, or to simply open <a href="https://bob.curvy.name" target="_blank" rel="noreferrer">https://bob.curvy.name</a> and continue with payment there.</p><p>Bob made it clear that <strong>he only accepts payment in USDC, but hasn&#39;t specified which network to use</strong>.</p><p>Without asking, Alice sent the funds to Bob&#39;s private address on Ethereum, but was reassured by Bob that <em>the system he&#39;s using should pick up transfers on any of the <a href="/for-users/#supported-networks-and-tokens">supported networks</a> — Polygon, BSC, Arbitrum, Optimism, Linea, Base, Gnosis, or even Solana.</em></p><p><strong>Bob uses Curvy, but Alice, the sender, can keep using Ledger + MetaMask without knowing what Curvy is.</strong></p><p><img src="'+o+'" alt="Receiving funds privately"></p><h2 id="steps-explained-in-detail" tabindex="-1">Steps explained in detail <a class="header-anchor" href="#steps-explained-in-detail" aria-label="Permalink to &quot;Steps explained in detail&quot;">​</a></h2><h3 id="🔵-alice" tabindex="-1">🔵 Alice <a class="header-anchor" href="#🔵-alice" aria-label="Permalink to &quot;🔵 Alice&quot;">​</a></h3><p><strong>1.</strong> Alice enters <code>bob.curvy.name</code> into her wallet of choice. In the background, an <strong>ENS resolver</strong> powered by the <strong>Curvy SDK</strong> fetches Bob&#39;s public keys from the <strong>Identity Registry</strong>.</p><p><strong>2.</strong> Using the <strong>Curvy SDK</strong>, a random nonce, and Bob&#39;s public keys, a new <strong>Portal</strong> address is generated to which Bob can receive funds; no contract is deployed at that address yet. The resolved Portal is recorded so that the <strong>Portal Broadcasters</strong> can later pick it up.</p><p><strong>3.</strong> Alice sends the funds to the generated Portal address, as she would to any regular address.</p><h3 id="⚫-curvy" tabindex="-1">⚫ Curvy <a class="header-anchor" href="#⚫-curvy" aria-label="Permalink to &quot;⚫ Curvy&quot;">​</a></h3><p><strong>4.</strong> After observing that a Portal address has received any of the supported funds, the <strong>Portal Broadcasters</strong> have the necessary incentive to deploy the <strong>Portal</strong> contract through the <strong>Portal Factory</strong>. Because the address of the Portal is deterministically calculated, the deployment lands exactly where the funds are: on networks without the aggregator, an entry Portal automatically bridges the funds over the cross-chain bridge; on the network with the aggregator, a shielding Portal shields them directly into the <strong>Privacy Aggregator</strong> (<strong>Aggregator.sol</strong>).</p><p><strong>6.</strong> The <strong>Batch Prover</strong> picks up the pending shielded notes, constructs a commitment proof for the new notes batch, and commits it on-chain to <strong>Aggregator.sol</strong>. After successful on-chain verification, the new note becomes part of the committed Notes tree.</p><h3 id="🟢-bob" tabindex="-1">🟢 Bob <a class="header-anchor" href="#🟢-bob" aria-label="Permalink to &quot;🟢 Bob&quot;">​</a></h3><p><strong>7.</strong> Some unknown time later, Bob logs into his <strong>Curvy App</strong>. In the background, immediately upon starting, the Curvy App, using the open-source <strong>Curvy SDK</strong>, syncs its local Merkle tree from the <strong>Indexer</strong>, which serves as a fast index of on-chain events emitted by <strong>Aggregator.sol</strong>.</p><p><img src="'+a+'" alt="Receiver flow"></p><p>In Bob&#39;s browser, the <strong>Curvy SDK</strong> simultaneously scans the synced notes with his private keys to detect which notes are secretly in his ownership and to decrypt their balances.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Steps <strong>5a/5b</strong> (transfer proofs) and <strong>8</strong> (withdrawal request) from the drawing above belong to the other two flows: <a href="./sending-funds-privately.html">Sending funds privately</a> and <a href="./unshielding-funds-privately.html">Unshielding funds privately</a>.</p></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>From the perspective of an on-chain observer, Alice has sent funds to a regular EOA address to which a smart contract (Portal) was later deployed by the Portal Broadcaster. This deployment moved the funds to the Curvy Privacy Protocol (Aggregator.sol), <strong>and most importantly, the new owner of these funds (Bob) is completely hidden</strong>.</p></div>',22)])])}const v=t(i,[["render",h]]);export{y as __pageData,v as default};
